ArtBlackHole.UseScript:
if ship.CurrentStar == nil then
  return { ok=false, message=string.format('[Активация] %s: корабль не в системе.', item.Name) }
end
local radius = Api.GetConfigFloat(cfg, item, 'SpawnRadius', 5)
local wh = Api.SpawnWormholeNearShip(ship, radius)
if wh == nil then
  return { ok=false, message=string.format('[Активация] %s: не удалось создать субпортал.', item.Name) }
end
return { ok=true, consume=true, message=string.format('[Активация] %s: субпортал открыт в системе %s.', item.Name, ship.CurrentStar.Name) }

ArtTransmitter.UseScript:
if ship.CurrentStar == nil then
  return { ok=false, message=string.format('[Активация] %s: корабль не в системе.', item.Name) }
end
if not Api.SummonSideFromConfig(ship, cfg, item, 'Summon') then
  return { ok=false, message=string.format('[Активация] %s: призыв не удался.', item.Name) }
end
return { ok=true, consume=true, message=string.format('[Активация] %s: сторона направлена в %s.', item.Name, ship.CurrentStar.Name) }
